<section class="apo-call" id="apo-private-call" data-active-url="{{ $activeUrl }}" data-start-url="{{ $startUrl }}" data-poll-url="{{ $pollUrl }}" data-signal-url="{{ $signalUrl }}" data-recording-url="{{ $recordingUrl }}" data-finish-url="{{ $finishUrl }}" data-retention-days="{{ $retentionDays }}" data-csrf="{{ csrf_token() }}">
  <div class="apo-call-head"><span class="apo-call-icon" aria-hidden="true">☎</span><div><h2>Özel sesli ve görüntülü görüşme</h2><p>Yalnızca bu rezervasyonun müşterisi ve tesis yetkilisi görüşebilir. Arama, konaklama başladıktan sonra kullanılabilir.</p></div></div>
  <div class="apo-call-disclosure">Görüşme sırasında ses ve görüntü kaydı varsayılan olarak alınmaz. İki taraf da aydınlatma bilgisini okuduktan sonra kayıt için ayrı ve isteğe bağlı açık rıza verirse kayıt şifreli olarak saklanır, yalnızca bu rezervasyonun taraflarına açılır ve {{ $retentionDays }} gün sonra silinir. Rıza vermemeniz görüşmeye katılmanızı engellemez. <a href="{{ url('/sayfa/gizlilik') }}" target="_blank" rel="noopener">Gizlilik ve ilgili kişi hakları</a></div>
  <label class="apo-call-consent"><input type="checkbox" data-call-notice><span>Görüşme ve kayıt aydınlatma bilgisini okudum.</span></label>
  <label class="apo-call-consent"><input type="checkbox" data-call-consent><span>(İsteğe bağlı) Görüşmemin belirtilen amaç ve süreyle kaydedilmesine açık rıza veriyorum. Bu kutuyu işaretlemezseniz görüşme kaydedilmez.</span></label>
  <div class="apo-call-controls"><button type="button" data-call-start="video">Görüntülü ara</button><button type="button" class="apo-call-secondary" data-call-start="audio">Sesli ara</button></div>
  <div class="apo-call-state" role="status" aria-live="polite">Görüşme başlatmak için arama türünü seçin.</div>
  <div class="apo-call-incoming" hidden><b>Gelen arama</b><span data-call-incoming-label>Bu rezervasyon için arama geliyor.</span><label class="apo-call-consent"><input type="checkbox" data-call-notice-incoming><span>Görüşme ve kayıt aydınlatma bilgisini okudum.</span></label><label class="apo-call-consent"><input type="checkbox" data-call-consent-incoming><span>(İsteğe bağlı) Kayıt için ayrı açık rıza veriyorum. Onaylamazsanız görüşme kaydedilmez.</span></label><button type="button" data-call-accept>Kabul et ve görüşmeye katıl</button><button type="button" data-call-reject>Reddet</button></div>
  <div class="apo-call-media" hidden>
    <div class="apo-call-screen apo-call-main-screen">
      <video class="apo-call-remote" autoplay playsinline></video>
      <span class="apo-call-placeholder apo-call-remote-placeholder">Karşı taraf bağlanınca görüntüsü burada görünecek.</span>
      <div class="apo-call-overlay">
        <div class="apo-call-device-controls">
          <audio class="apo-call-remote-audio" autoplay playsinline controls hidden></audio>
          <button type="button" class="apo-call-icon-button" data-call-mic aria-label="Mikrofonu sessize al" title="Mikrofonu sessize al" aria-pressed="false" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/></svg><span class="apo-call-sr-only">Mikrofonu sessize al</span></button>
          <button type="button" class="apo-call-icon-button" data-call-video aria-label="Kamerayı kapat" title="Kamerayı kapat" aria-pressed="false" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="6" width="12" height="12" rx="2"/><path d="m15 10 6-3v10l-6-3"/></svg><span class="apo-call-sr-only">Kamerayı kapat</span></button>
          <button type="button" class="apo-call-icon-button" data-call-camera aria-label="Arka kameraya geç" title="Arka kameraya geç" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.6 9A7 7 0 0 1 18 6l2 2M4 16l2 2a7 7 0 0 0 12.4-3"/></svg><span class="apo-call-sr-only">Arka kameraya geç</span></button>
          <button type="button" class="apo-call-overlay-text" data-call-mode hidden>Yalnızca sesli görüş</button>
          <button type="button" class="apo-call-overlay-text" data-call-audio hidden>Sesi aç</button>
          <button type="button" class="apo-call-overlay-text" data-call-output aria-pressed="false" hidden>Hoparlöre geç</button>
        </div>
        <button class="apo-call-icon-button apo-call-hangup" type="button" data-call-end aria-label="Aramayı sonlandır" title="Aramayı sonlandır" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 15.2c4.7-3.5 10.3-3.5 15 0l1.1.8-2.2 4.1a1.6 1.6 0 0 1-1.9.7l-3-1.1a1.6 1.6 0 0 1-1-1.5v-1a12 12 0 0 0-1.1 0v1a1.6 1.6 0 0 1-1 1.5l-3 1.1a1.6 1.6 0 0 1-1.9-.7l-2.2-4.1z"/></svg><span class="apo-call-sr-only">Aramayı sonlandır</span></button>
      </div>
    </div>
    <div class="apo-call-screen apo-call-local-screen"><video class="apo-call-local" autoplay playsinline muted></video><span class="apo-call-placeholder apo-call-local-placeholder">Kamera önizlemesi hazırlanıyor…</span></div>
  </div>
</section>
<style>
.apo-call{margin:16px 0;padding:18px;border:1px solid #e8e7df;border-radius:18px;background:linear-gradient(135deg,#fffaf5,#f7fbf7);box-shadow:0 8px 24px #2431260a}.apo-call-head{display:flex;align-items:flex-start;gap:12px}.apo-call-icon{display:grid;place-items:center;width:42px;height:42px;flex:none;border-radius:13px;background:#fff0e9;color:#f04418;font-size:21px}.apo-call h2{margin:1px 0 5px;color:#252c27;font-size:18px}.apo-call p,.apo-call-state{margin:0;color:#66736a;font-size:13px;line-height:1.6}.apo-call-consent{display:flex;align-items:flex-start;gap:9px;margin-top:14px;padding:11px;border:1px solid #e9e6da;border-radius:12px;background:#fff;color:#58645c;font-size:11px;line-height:1.55}.apo-call-consent input{margin-top:2px;accent-color:#f04418}.apo-call-consent a{color:#c83b19;text-decoration:underline}.apo-call-controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.apo-call button{min-height:40px;padding:9px 14px;border:0;border-radius:11px;background:#f04418;color:#fff;font:700 13px inherit;cursor:pointer}.apo-call button:hover{filter:brightness(.96)}.apo-call button:disabled{opacity:.55;cursor:wait}.apo-call .apo-call-secondary{border:1px solid #e1e5df;background:#fff;color:#303a33}.apo-call-state{padding-top:11px}.apo-call-incoming{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:12px;padding:12px;border:1px solid #efd2a0;border-radius:12px;background:#fff9eb}.apo-call-incoming>span{flex:1 1 100%;color:#5f5749;font-size:13px}.apo-call-incoming .apo-call-consent{flex:1 1 100%}.apo-call-incoming button{min-height:36px}.apo-call-incoming [data-call-reject],.apo-call-end{background:#fff!important;color:#9a3b26!important;border:1px solid #ebc9bf!important}.apo-call-media{display:grid;grid-template-columns:2fr 1fr;gap:8px;margin-top:12px}.apo-call-screen{position:relative;min-width:0;overflow:hidden;border-radius:12px;background:#1c2520;aspect-ratio:16/9}.apo-call-media video{display:block;width:100%;height:100%;max-height:320px;object-fit:cover;background:#1c2520}.apo-call-local-screen{max-height:180px}.apo-call-audio-only .apo-call-screen{display:grid;place-items:center;min-height:88px;max-height:none;aspect-ratio:auto}.apo-call-audio-only .apo-call-screen video{display:none}.apo-call-remote-audio-only .apo-call-screen:first-child video{display:none}.apo-call-placeholder{position:absolute;inset:0;display:grid;place-items:center;padding:18px;color:#e7eee9;text-align:center;font-size:13px;line-height:1.5;background:linear-gradient(135deg,#1c2520,#29352e)}.apo-call-overlay{position:absolute;inset:auto 0 0;z-index:4;display:flex;align-items:center;justify-content:center;gap:14px;padding:42px 14px 15px;background:linear-gradient(0deg,rgba(9,16,12,.82),rgba(9,16,12,0))}.apo-call-device-controls{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:10px;margin:0}.apo-call-device-controls audio{width:min(100%,360px);height:40px}.apo-call-icon-button{display:grid;place-items:center;width:52px;min-width:52px;height:52px;min-height:52px;padding:0!important;border:1px solid rgba(255,255,255,.22)!important;border-radius:50%!important;background:rgba(255,255,255,.17)!important;color:#fff!important;box-shadow:0 4px 14px rgba(0,0,0,.18);backdrop-filter:blur(12px)}.apo-call-icon-button svg{width:23px;height:23px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.apo-call-icon-button[aria-pressed="true"]{background:#fff!important;color:#242a26!important}.apo-call-icon-button.apo-call-hangup{background:#e53935!important;color:#fff!important;border-color:#e53935!important}.apo-call-overlay-text{min-height:38px!important;padding:8px 11px!important;border:1px solid rgba(255,255,255,.24)!important;border-radius:999px!important;background:rgba(255,255,255,.15)!important;color:#fff!important;font-size:11px!important;backdrop-filter:blur(12px)}.apo-call-sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.apo-call [data-call-end]{margin:0}.apo-call [hidden]{display:none!important}@media(max-width:560px){.apo-call{padding:14px}.apo-call h2{font-size:16px}.apo-call-media{grid-template-columns:1fr}.apo-call-media .apo-call-local{max-height:220px}}
</style>
<script>
(function(){
  const box=document.querySelector('.apo-call[data-active-url]');if(!box)return;
  const activeUrl=box.dataset.activeUrl,startUrl=box.dataset.startUrl,pollTemplate=box.dataset.pollUrl,signalTemplate=box.dataset.signalUrl,recordingTemplate=box.dataset.recordingUrl,finishTemplate=box.dataset.finishUrl,csrf=box.dataset.csrf;
  const state=box.querySelector('.apo-call-state'),incoming=box.querySelector('.apo-call-incoming'),media=box.querySelector('.apo-call-media'),remoteVideo=box.querySelector('.apo-call-remote'),remoteAudio=box.querySelector('.apo-call-remote-audio'),audioButton=box.querySelector('[data-call-audio]'),outputButton=box.querySelector('[data-call-output]'),cameraButton=box.querySelector('[data-call-camera]'),micButton=box.querySelector('[data-call-mic]'),videoToggleButton=box.querySelector('[data-call-video]'),modeButton=box.querySelector('[data-call-mode]'),localVideo=box.querySelector('.apo-call-local'),remotePlaceholder=box.querySelector('.apo-call-remote-placeholder'),localPlaceholder=box.querySelector('.apo-call-local-placeholder'),endButton=box.querySelector('[data-call-end]');
  const setCallControlLabel=(button,label)=>{button.setAttribute('aria-label',label);button.title=label;const text=button.querySelector('.apo-call-sr-only');if(text)text.textContent=label};
  let callId=null,callStatus=null,callerId=null,currentUser=null,mediaType='video',recordingAllowed=false,pc=null,localStream=null,iceServers=[{urls:'stun:stun.l.google.com:19302'}],iceTransportPolicy='all',lastSignal=0,polling=false,initializing=false,syncTimer=null,syncDelay=2500,offerStarted=false,iceQueue=[],recorder=null,canvas=null,drawFrame=0,sequence=0,uploadChain=Promise.resolve(),recorderDone=null,audioContext=null,ringbackContext=null,ringbackTimer=null,ringbackActive=false,incomingToneActive=false,incomingToneTimer=null,audioOnlyMode=false,recordingFinalized=false,facingMode='user',speakerMode=false,earpieceOutputId=null,defaultOutputId='default',originalAudioSessionType=null;
  const pollUrl=()=>pollTemplate.replace('CALL_UUID',encodeURIComponent(callId));
  const signalUrl=()=>signalTemplate.replace('CALL_UUID',encodeURIComponent(callId));
  const recordingUrl=()=>recordingTemplate.replace('CALL_UUID',encodeURIComponent(callId));
  const finishUrl=()=>finishTemplate.replace('CALL_UUID',encodeURIComponent(callId));
  async function post(url,data){const controller=new AbortController(),timer=window.setTimeout(()=>controller.abort(),15000);try{const r=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(data),signal:controller.signal});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.message||(r.status===429?'Çok fazla istek gönderildi. Lütfen biraz bekleyip tekrar deneyin.':'İstek tamamlanamadı.'));return j}catch(e){if(e&&e.name==='AbortError')throw new Error('Sunucu 15 saniye içinde yanıt vermedi. Bağlantıyı kontrol edip yeniden deneyin.');throw e}finally{window.clearTimeout(timer)}}
  async function send(type,payload){return post(signalUrl(),{type:type,payload:payload||null})}
  function status(text){state.textContent=text}
  function requestEarpieceRoute(){try{const session=navigator.audioSession;if(!session)return false;if(originalAudioSessionType===null)originalAudioSessionType=session.type||'auto';session.type='play-and-record';return true}catch(_){return false}}
  function restoreAudioRoute(){try{if(navigator.audioSession&&originalAudioSessionType!==null)navigator.audioSession.type=originalAudioSessionType}catch(_){}originalAudioSessionType=null}
  async function toggleAudioOutput(){if(speakerMode){try{if(typeof remoteAudio.setSinkId==='function')await remoteAudio.setSinkId(earpieceOutputId||defaultOutputId);speakerMode=false;requestEarpieceRoute();outputButton.textContent='Hoparlöre geç';outputButton.setAttribute('aria-pressed','false');status('Ses ahizeye yönlendirildi.')}catch(_){status('Ses ahizeye alınamadı. Cihazın ses çıkış ayarını kontrol edin.')}return}if(typeof remoteAudio.setSinkId!=='function'){status('Bu mobil tarayıcı hoparlör seçimini web sitelerine açmıyor. Arama ahizede başlatıldı; hoparlör için telefonun ses çıkış menüsünü kullanın.');return}try{const devices=await navigator.mediaDevices.enumerateDevices();let output=devices.find(d=>d.kind==='audiooutput'&&/(speaker|loudspeaker|hoparlör)/i.test(d.label));if(!output&&typeof navigator.mediaDevices.selectAudioOutput==='function')output=await navigator.mediaDevices.selectAudioOutput();if(!output){status('Tarayıcı bu cihazda seçilebilir hoparlör çıkışı sunmuyor.');return}earpieceOutputId=devices.find(d=>d.kind==='audiooutput'&&/(earpiece|receiver|handset|ahize)/i.test(d.label))?.deviceId||null;defaultOutputId=remoteAudio.sinkId||'default';await remoteAudio.setSinkId(output.deviceId);speakerMode=true;outputButton.textContent='Ahizeye geç';outputButton.setAttribute('aria-pressed','true');status('Ses hoparlöre yönlendirildi.')}catch(e){status(e&&e.name==='NotAllowedError'?'Ses çıkışını değiştirmek için tarayıcı izni gerekiyor.':'Hoparlör çıkışı değiştirilemedi. Cihazın ses ayarını kontrol edin.')}}
  function prepareRingback(){if(!window.AudioContext&&!window.webkitAudioContext)return;try{const AudioCtor=window.AudioContext||window.webkitAudioContext;if(!ringbackContext)ringbackContext=new AudioCtor();if(ringbackContext.state==='suspended')ringbackContext.resume().catch(()=>{})}catch(_){}}
  function ringToneAt(offset,duration){if(!ringbackContext||ringbackContext.state==='closed')return;const oscillator=ringbackContext.createOscillator(),gain=ringbackContext.createGain(),start=ringbackContext.currentTime+offset;oscillator.type='sine';oscillator.frequency.value=425;gain.gain.setValueAtTime(0.0001,start);gain.gain.exponentialRampToValueAtTime(0.055,start+0.05);gain.gain.setValueAtTime(0.055,start+duration-0.05);gain.gain.exponentialRampToValueAtTime(0.0001,start+duration);oscillator.connect(gain);gain.connect(ringbackContext.destination);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()};oscillator.start(start);oscillator.stop(start+duration)}
  function startRingback(){if(ringbackActive)return;prepareRingback();if(!ringbackContext)return;ringbackActive=true;const cycle=()=>{if(!ringbackActive)return;ringToneAt(0,0.85);ringToneAt(1.2,0.85);ringbackTimer=window.setTimeout(cycle,5000)};cycle()}
  function stopRingback(){ringbackActive=false;if(ringbackTimer)window.clearTimeout(ringbackTimer);ringbackTimer=null}
  function incomingToneAt(offset,duration){if(!ringbackContext||ringbackContext.state==='closed')return;const oscillator=ringbackContext.createOscillator(),gain=ringbackContext.createGain(),start=ringbackContext.currentTime+offset;oscillator.type='sine';oscillator.frequency.value=660;gain.gain.setValueAtTime(0.0001,start);gain.gain.exponentialRampToValueAtTime(0.07,start+0.04);gain.gain.setValueAtTime(0.07,start+duration-0.04);gain.gain.exponentialRampToValueAtTime(0.0001,start+duration);oscillator.connect(gain);gain.connect(ringbackContext.destination);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()};oscillator.start(start);oscillator.stop(start+duration)}
  function startIncomingTone(){if(incomingToneActive)return;prepareRingback();if(!ringbackContext)return;incomingToneActive=true;const cycle=()=>{if(!incomingToneActive)return;incomingToneAt(0,0.35);incomingToneAt(0.55,0.35);incomingToneTimer=window.setTimeout(cycle,2400)};cycle()}
  function stopIncomingTone(){incomingToneActive=false;if(incomingToneTimer)window.clearTimeout(incomingToneTimer);incomingToneTimer=null}
  async function stopRecording(){if(recorder&&recorder.state!=='inactive'){recorder.stop();await recorderDone}try{await uploadChain;if(callId&&sequence>0&&!recordingFinalized){await post(finishUrl(),{});recordingFinalized=true}}catch(_){}recorder=null;if(drawFrame)cancelAnimationFrame(drawFrame);if(audioContext){audioContext.close().catch(()=>{});audioContext=null}}
  function stopMedia(){stopIncomingTone();restoreAudioRoute();speakerMode=false;outputButton.hidden=true;outputButton.textContent='Hoparlöre geç';outputButton.setAttribute('aria-pressed','false');audioOnlyMode=false;modeButton.hidden=true;modeButton.textContent='Yalnızca sesli görüş';media.classList.remove('apo-call-audio-only','apo-call-remote-audio-only');if(pc){pc.onicecandidate=null;pc.close();pc=null}if(localStream){localStream.getTracks().forEach(t=>t.stop());localStream=null}remoteVideo.srcObject=null;remoteAudio.pause();remoteAudio.srcObject=null;remoteAudio.hidden=true;audioButton.hidden=true;cameraButton.hidden=true;micButton.hidden=true;videoToggleButton.hidden=true;modeButton.hidden=true;setCallControlLabel(micButton,'Mikrofonu sessize al');micButton.setAttribute('aria-pressed','false');setCallControlLabel(videoToggleButton,'Kamerayı kapat');videoToggleButton.setAttribute('aria-pressed','false');localVideo.srcObject=null;media.hidden=true;endButton.hidden=true;iceQueue=[]}
  async function finish(text){stopRingback();await stopRecording();stopMedia();incoming.hidden=true;callStatus=null;callId=null;callerId=null;initializing=false;offerStarted=false;status(text)}
  async function getMedia(type){if(type==='audio'||audioOnlyMode)requestEarpieceRoute();else restoreAudioRoute();if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia)throw new Error('Bu cihazda kamera/mikrofon erişimi yok. Sayfayı HTTPS üzerinden açın.');let settled=false,timer=null;const request=navigator.mediaDevices.getUserMedia({audio:true,video:type==='video'?{facingMode:{ideal:facingMode}}:false}).then(stream=>{if(settled){stream.getTracks().forEach(track=>track.stop());throw new Error('İzin isteği zaman aşımına uğradı. Yeniden deneyin.')}return stream});const timeout=new Promise((_,reject)=>{timer=window.setTimeout(()=>{settled=true;reject(new Error('Tarayıcı izin penceresi yanıt vermedi. Adres çubuğundaki site izinlerinden kamera ve mikrofonu açıp yeniden deneyin.'))},45000)});try{localStream=await Promise.race([request,timeout])}catch(e){if(e&&['NotAllowedError','PermissionDeniedError'].includes(e.name))throw new Error('Kamera/mikrofon izni verilmedi. Adres çubuğundaki site izinlerinden izin verip yeniden deneyin.');if(e&&e.name==='NotFoundError')throw new Error('Bu cihazda istenen kamera veya mikrofon bulunamadı.');if(e&&e.name==='NotReadableError')throw new Error('Kamera veya mikrofon başka bir uygulama tarafından kullanılıyor.');throw e}finally{if(timer)window.clearTimeout(timer);settled=true}localVideo.srcObject=localStream;cameraButton.hidden=type!=='video';setCallControlLabel(cameraButton,facingMode==='user'?'Arka kameraya geç':'Ön kameraya geç');videoToggleButton.hidden=type!=='video';modeButton.hidden=true;micButton.hidden=false;outputButton.hidden=!(type==='audio'||audioOnlyMode);outputButton.textContent='Hoparlöre geç';outputButton.setAttribute('aria-pressed','false');speakerMode=false;modeButton.textContent='Yalnızca sesli görüş';audioOnlyMode=false;audioButton.hidden=true;media.classList.toggle('apo-call-audio-only',type==='audio');if(type==='audio'){localPlaceholder.textContent='Mikrofon açık · sesli görüşme';remotePlaceholder.textContent='Diğer tarafın araması bekleniyor…'}else{localVideo.addEventListener('loadeddata',()=>{localPlaceholder.hidden=true},{once:true});localVideo.play().catch(()=>{});window.setTimeout(()=>{if(localVideo.readyState>=2&&localVideo.videoWidth>0)localPlaceholder.hidden=true},5000)}media.hidden=false;endButton.hidden=false}
  function normalizeSdp(d){if(!d||typeof d!=='object')return d;const value={...d};if(typeof value.sdp==='string'){const eol=String.fromCharCode(13)+String.fromCharCode(10);value.sdp=value.sdp.split(eol).join('\n').split('\r').join('\n').split('\n').join(eol);if(!value.sdp.endsWith(eol))value.sdp+=eol}return value}
  function applyIce(d){if(Array.isArray(d.ice_servers)&&d.ice_servers.length)iceServers=d.ice_servers;if(d.ice_transport_policy==='relay'||d.ice_transport_policy==='all')iceTransportPolicy=d.ice_transport_policy}function makePeer(){if(pc)return pc;pc=new RTCPeerConnection({iceServers:iceServers,iceTransportPolicy:iceTransportPolicy});localStream.getTracks().forEach(t=>pc.addTrack(t,localStream));pc.ontrack=e=>{const remoteStream=e.streams[0]||new MediaStream([e.track]);remoteVideo.srcObject=remoteStream;remoteVideo.muted=true;const audioStream=new MediaStream(remoteStream.getAudioTracks());if(audioStream.getAudioTracks().length){remoteAudio.srcObject=audioStream;remoteAudio.hidden=false;remoteAudio.play().then(()=>{audioButton.hidden=true}).catch(()=>{audioButton.hidden=false;status('Görüntü bağlandı. Sesi duymak için “Sesi aç” düğmesine dokunun.')})}if(mediaType==='audio'){remotePlaceholder.hidden=false;remotePlaceholder.textContent='Sesli görüşme bağlantısı kuruldu.';remoteVideo.play().catch(()=>{})}else{remoteVideo.play().then(()=>{remotePlaceholder.hidden=true}).catch(()=>{remotePlaceholder.textContent='Karşı taraf bağlandı. Görüntüyü görmek için oynat simgesine dokunun.'})}if(callerId===currentUser)startRecording()};pc.onicecandidate=e=>{if(e.candidate&&callId)send('ice',e.candidate.toJSON()).catch(()=>{})};pc.onconnectionstatechange=()=>{if(!pc)return;if(pc.connectionState==='connected'){status('Görüşme bağlantısı kuruldu.');modeButton.hidden=mediaType!=='video'}else if(pc.connectionState==='failed'){end('end','Görüşme bağlantısı kurulamadı. Ağ izni veya internet bağlantısını kontrol edip yeniden deneyin.')}};return pc}
  function startRecording(){if(!recordingAllowed||recorder||callerId!==currentUser||!localStream||!remoteVideo.srcObject)return;if(!window.MediaRecorder){status('Görüşme bağlı; tarayıcı kayıt desteği sunmadığı için kayıt alınmıyor.');return}try{const tracks=[];if(mediaType==='video'){canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;const ctx=canvas.getContext('2d');const draw=()=>{ctx.fillStyle='#17211c';ctx.fillRect(0,0,960,540);if(!audioOnlyMode&&localVideo.readyState>=2)ctx.drawImage(localVideo,0,0,480,540);if(!media.classList.contains('apo-call-remote-audio-only')&&remoteVideo.readyState>=2)ctx.drawImage(remoteVideo,480,0,480,540);drawFrame=requestAnimationFrame(draw)};draw();tracks.push(...canvas.captureStream(15).getVideoTracks())}audioContext=new (window.AudioContext||window.webkitAudioContext)();const destination=audioContext.createMediaStreamDestination();[localStream,remoteVideo.srcObject].forEach(stream=>stream.getAudioTracks().forEach(track=>audioContext.createMediaStreamSource(new MediaStream([track])).connect(destination)));tracks.push(...destination.stream.getAudioTracks());const stream=new MediaStream(tracks);const mime=mediaType==='audio'&&MediaRecorder.isTypeSupported('audio/webm;codecs=opus')?'audio/webm;codecs=opus':(MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus')?'video/webm;codecs=vp8,opus':'video/webm');recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:220000,audioBitsPerSecond:32000});sequence=0;recorderDone=new Promise(resolve=>recorder.addEventListener('stop',resolve,{once:true}));recorder.ondataavailable=e=>{if(!e.data||!e.data.size)return;const index=sequence++,form=new FormData();form.append('sequence',index);form.append('chunk',e.data,'call-'+index+'.webm');uploadChain=uploadChain.then(()=>fetch(recordingUrl(),{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:form})).then(r=>{if(!r.ok)throw new Error('Kayıt parçası sunucuya aktarılamadı.')}).catch(e=>status(e.message))};recorder.start(10000);status('Görüşme şifreli kaydediliyor ve güvenli depoya aktarılıyor.')}catch(e){status('Görüşme bağlı; kayıt başlatılamadığı için kayıt alınmıyor.')}}
  async function processSignal(s){if(s.type==='offer'&&callerId!==currentUser&&!pc)return;if(s.id)lastSignal=Math.max(lastSignal,Number(s.id));if(s.type==='offer'&&callerId!==currentUser){await pc.setRemoteDescription(normalizeSdp(s.payload));for(const c of iceQueue.splice(0))try{await pc.addIceCandidate(c)}catch(_){}const answer=await pc.createAnswer();await pc.setLocalDescription(answer);await send('answer',pc.localDescription.toJSON?pc.localDescription.toJSON():{type:pc.localDescription.type,sdp:pc.localDescription.sdp});status('Görüşme bağlandı.');return}if(s.type==='answer'&&callerId===currentUser&&pc&&!pc.remoteDescription){await pc.setRemoteDescription(normalizeSdp(s.payload));for(const c of iceQueue.splice(0))try{await pc.addIceCandidate(c)}catch(_){}status('Görüşme bağlandı.')}if(s.type==='ice'&&s.payload&&['audio','video'].includes(s.payload.__apo_mode)){if(s.payload.__apo_mode==='audio'){media.classList.add('apo-call-remote-audio-only');remotePlaceholder.textContent='Diğer taraf yalnızca sesli görüşüyor.';remotePlaceholder.hidden=false}else{media.classList.remove('apo-call-remote-audio-only');remotePlaceholder.textContent='Karşı taraf bağlanınca görüntüsü burada görünecek.';if(remoteVideo.readyState>=2)remotePlaceholder.hidden=true}return}if(s.type==='ice'&&s.payload){if(!pc||!pc.remoteDescription)iceQueue.push(s.payload);else try{await pc.addIceCandidate(s.payload)}catch(_){}}}
  async function startOffer(){if(offerStarted||!localStream||callerId!==currentUser)return;offerStarted=true;mediaType=callStatus==='accepted'?mediaType:mediaType;const p=makePeer();const offer=await p.createOffer();await p.setLocalDescription(offer);await send('offer',p.localDescription.toJSON? p.localDescription.toJSON():{type:p.localDescription.type,sdp:p.localDescription.sdp});status('Görüşme bağlanıyor…')}
  async function sync(){if(polling)return;polling=true;try{if(!callId){const active=await fetch(activeUrl,{credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},cache:'no-store'});if(!active.ok){if(active.status===429){syncDelay=Math.min(syncDelay*2,60000);status('Çok sık bağlantı kontrolü yapıldı. Yeniden deneniyor…')}return;}const found=await active.json();syncDelay=2500;if(!found.call_id)return;callId=found.call_id;lastSignal=0;recordingFinalized=false}const r=await fetch(pollUrl()+'?after='+lastSignal,{credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},cache:'no-store'});if(!r.ok){if(r.status===429){syncDelay=Math.min(syncDelay*2,60000);status('Bağlantı sınırına ulaşıldı. Biraz bekleyip yeniden deniyorum…');return}if(r.status>=500){status('Bağlantı geçici olarak yoğun; yeniden deneniyor…');return}await finish('Görüşme bağlantısı sona erdi.');return}syncDelay=2500;const d=await r.json();applyIce(d);callStatus=d.status;callerId=d.caller_id;currentUser=d.current_user_id;mediaType=d.media_type;recordingAllowed=!!d.recording_allowed;if(d.status==='ringing'&&callerId!==currentUser){stopRingback();incoming.hidden=false;startIncomingTone();box.querySelector('[data-call-incoming-label]').textContent=d.media_type==='video'?'Bu rezervasyon için görüntülü arama geliyor.':'Bu rezervasyon için sesli arama geliyor.';status('Gelen arama yanıtınızı bekliyor.')}else if(d.status==='ringing'){stopIncomingTone();incoming.hidden=true;startRingback();status('Telefon çalıyor; karşı tarafın yanıtı bekleniyor…')}else if(d.status==='accepted'){stopRingback();stopIncomingTone();incoming.hidden=true;if(callerId===currentUser)await startOffer();else status('Görüşme hazırlanıyor…')}else if(['rejected','ended','missed'].includes(d.status)){await finish(d.status==='rejected'?'Arama reddedildi.':'Görüşme sonlandı.');return}for(const s of d.signals||[])await processSignal(s)}catch(e){status(e.message||'Arama bağlantısı yenileniyor…')}finally{polling=false;if(syncTimer)clearTimeout(syncTimer);syncTimer=window.setTimeout(sync,syncDelay)}}
  async function begin(type){try{if(!window.RTCPeerConnection)throw new Error('Bu tarayıcı güvenli ses ve görüntü aramasını desteklemiyor.');if(!box.querySelector('[data-call-notice]').checked)throw new Error('Önce görüşme ve kayıt aydınlatma bilgisini okuduğunuzu onaylayın.');box.querySelectorAll('[data-call-start]').forEach(b=>b.disabled=true);mediaType=type;prepareRingback();status(type==='video'?'Kamera ve mikrofon izni bekleniyor…':'Mikrofon izni bekleniyor…');await getMedia(type);status(type==='video'?'Kamera açıldı; arama başlatılıyor…':'Mikrofon açıldı; arama başlatılıyor…');const result=await post(startUrl,{media_type:type,notice_read:true,recording_consent:box.querySelector('[data-call-consent]').checked});callId=result.call_id;applyIce(result);lastSignal=0;recordingFinalized=false;callStatus='ringing';startRingback();status('Telefon çalıyor; karşı tarafın yanıtı bekleniyor…');endButton.hidden=false;sync()}catch(e){if(callId){try{await send('end')}catch(_){}await finish('Arama başlatılamadı: '+e.message)}else{stopMedia();status(e.message||'Arama başlatılamadı.')}}finally{box.querySelectorAll('[data-call-start]').forEach(b=>b.disabled=false)}}
  async function accept(){let acceptanceStarted=false;stopIncomingTone();try{if(!window.RTCPeerConnection)throw new Error('Bu tarayıcı ses ve görüntü aramasını desteklemiyor.');if(!box.querySelector('[data-call-notice-incoming]').checked)throw new Error('Önce görüşme ve kayıt aydınlatma bilgisini okuduğunuzu onaylayın.');incoming.hidden=true;initializing=true;const data=await fetch(pollUrl(),{credentials:'same-origin',headers:{Accept:'application/json'}}).then(r=>r.json());if(!data||data.status!=='ringing')throw new Error('Arama artık yanıt beklemiyor.');applyIce(data);callStatus=data.status;callerId=Number(data.caller_id);currentUser=Number(data.current_user_id);mediaType=data.media_type;await getMedia(mediaType);makePeer();acceptanceStarted=true;await send('accept',{notice_read:true,recording_consent:box.querySelector('[data-call-consent-incoming]').checked});const accepted=await fetch(pollUrl(),{credentials:'same-origin',headers:{Accept:'application/json'}}).then(r=>r.json());applyIce(accepted);callStatus=accepted.status;callerId=Number(accepted.caller_id);currentUser=Number(accepted.current_user_id);recordingAllowed=!!accepted.recording_allowed;initializing=false;status('Görüşme bağlanıyor…');sync()}catch(e){initializing=false;if(acceptanceStarted&&callId){try{await send('end')}catch(_){}await finish('Kamera veya mikrofon izni alınamadığı için görüşme sonlandırıldı.')}else{status(e.message);incoming.hidden=false}}}
  async function end(type,message){stopRingback();stopIncomingTone();await stopRecording();if(callId&&callStatus&&['ringing','accepted'].includes(callStatus)){try{await send(type||'end')}catch(_){}}await finish(message||'Görüşme sona erdi.');}
  function toggleMicrophone(){if(!localStream)return;const tracks=localStream.getAudioTracks();if(!tracks.length){status('Mikrofon bulunamadı.');return}const enable=tracks.some(track=>!track.enabled);tracks.forEach(track=>track.enabled=enable);setCallControlLabel(micButton,enable?'Mikrofonu sessize al':'Mikrofonu aç');micButton.setAttribute('aria-pressed',String(!enable));status(enable?'Mikrofon açık.':'Mikrofon sessize alındı.')}
  function toggleVideo(){if(!localStream||mediaType!=='video')return;const tracks=localStream.getVideoTracks();if(!tracks.length){status('Kamera bulunamadı.');return}const enable=tracks.some(track=>!track.enabled);tracks.forEach(track=>track.enabled=enable);setCallControlLabel(videoToggleButton,enable?'Kamerayı kapat':'Kamerayı aç');videoToggleButton.setAttribute('aria-pressed',String(!enable));if(enable){localVideo.play().catch(()=>{});if(localVideo.readyState>=2)localPlaceholder.hidden=true}else{localPlaceholder.textContent='Kameranız kapalı.';localPlaceholder.hidden=false}status(enable?'Kamera açıldı.':'Kamera kapatıldı.')}
  async function switchCallMode(){if(!localStream||mediaType!=='video'||!pc)return;const track=localStream.getVideoTracks()[0];const transceiver=pc.getTransceivers().find(item=>item.receiver&&item.receiver.track&&item.receiver.track.kind==='video');const sender=transceiver&&transceiver.sender;if(!track||!sender){status('Görüntü bağlantısı henüz hazır değil. Birkaç saniye sonra yeniden deneyin.');return}modeButton.disabled=true;try{if(!audioOnlyMode){await sender.replaceTrack(null);track.enabled=false;requestEarpieceRoute();outputButton.hidden=false;send('ice',{__apo_mode:'audio'}).catch(()=>{});audioOnlyMode=true;media.classList.add('apo-call-audio-only');localPlaceholder.textContent='Yalnızca sesli görüşme · kameranız kapalı.';localPlaceholder.hidden=false;remotePlaceholder.textContent='Yalnızca sesli görüşme';remotePlaceholder.hidden=false;videoToggleButton.hidden=true;cameraButton.hidden=true;modeButton.textContent='Görüntülü görüşmeye dön';status('Yalnızca sesli görüşmeye geçildi. Mikrofonunuz açık.')}else{track.enabled=true;await sender.replaceTrack(track);restoreAudioRoute();outputButton.hidden=mediaType!=='audio';send('ice',{__apo_mode:'video'}).catch(()=>{});audioOnlyMode=false;media.classList.remove('apo-call-audio-only');videoToggleButton.hidden=false;cameraButton.hidden=false;setCallControlLabel(videoToggleButton,'Kamerayı kapat');videoToggleButton.setAttribute('aria-pressed','false');modeButton.textContent='Yalnızca sesli görüş';remotePlaceholder.textContent='Karşı taraf bağlanınca görüntüsü burada görünecek.';if(remoteVideo.readyState>=2)remotePlaceholder.hidden=true;localVideo.play().catch(()=>{});if(localVideo.readyState>=2)localPlaceholder.hidden=true;status('Görüntülü görüşmeye dönüldü.')} }catch(e){status('Görüşme modu değiştirilemedi. Bağlantıyı kontrol edip tekrar deneyin.')}finally{modeButton.disabled=false}}
  async function switchCamera(){if(!localStream||mediaType!=='video')return;cameraButton.disabled=true;const next=facingMode==='user'?'environment':'user';let cameraStream;try{try{cameraStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{exact:next}}})}catch(_){cameraStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:next}}})}const nextTrack=cameraStream.getVideoTracks()[0];if(!nextTrack)throw new Error('Bu cihazda başka kamera bulunamadı.');const previous=localStream.getVideoTracks()[0];if(previous)nextTrack.enabled=previous.enabled;if(pc){const sender=pc.getSenders().find(item=>item.track&&item.track.kind==='video');if(sender)await sender.replaceTrack(nextTrack)}if(previous)localStream.removeTrack(previous);localStream.addTrack(nextTrack);if(previous)previous.stop();localVideo.srcObject=localStream;await localVideo.play().catch(()=>{});facingMode=next;setCallControlLabel(cameraButton,next==='user'?'Arka kameraya geç':'Ön kameraya geç');if(nextTrack.enabled)localPlaceholder.hidden=true;else{localPlaceholder.textContent='Kameranız kapalı.';localPlaceholder.hidden=false}status(next==='user'?'Ön kamera kullanılıyor.':'Arka kamera kullanılıyor.')}catch(e){status(e.message||'Kamera değiştirilemedi.');if(cameraStream)cameraStream.getTracks().forEach(track=>track.stop())}finally{cameraButton.disabled=false}}
  micButton.addEventListener('click',toggleMicrophone);
  videoToggleButton.addEventListener('click',toggleVideo);
  modeButton.addEventListener('click',switchCallMode);
  outputButton.addEventListener('click',toggleAudioOutput);
  audioButton.addEventListener('click',async()=>{try{await remoteAudio.play();audioButton.hidden=true;status('Görüşme bağlantısı kuruldu.')}catch(_){status('Ses açılamadı. Telefonun medya sesini ve tarayıcı ses iznini kontrol edin.')}});
  cameraButton.addEventListener('click',switchCamera);
  box.querySelectorAll('[data-call-start]').forEach(b=>b.addEventListener('click',()=>begin(b.dataset.callStart)));
  box.querySelector('[data-call-accept]').addEventListener('click',accept);
  box.querySelector('[data-call-reject]').addEventListener('click',()=>end('reject'));
  endButton.addEventListener('click',()=>end('end'));
  const resumeCallAudio=()=>{if(ringbackContext&&ringbackContext.state==='suspended')ringbackContext.resume().catch(()=>{})};document.addEventListener('pointerdown',resumeCallAudio,{passive:true});document.addEventListener('keydown',resumeCallAudio);
  sync();
})();
</script>
